class Solution {
final long MOD=1000000007;long pow(long a,long p){long r=1;while(p>0){if((p&1)!=0)r=r*a%MOD;a=a*a%MOD;p>>=1;}return r;}public int xorAfterQueries(int[] nums,int[][] queries){int n=nums.length,threshold=(int)Math.sqrt(n)+1;Map<Integer,List<int[]>> groups=new HashMap<>();for(int[] q:queries){int l=q[0],r=q[1],k=q[2],v=q[3];if(k>threshold){for(int i=l;i<=r;i+=k)nums[i]=(int)((long)nums[i]*v%MOD);}else groups.computeIfAbsent(k,x->new ArrayList<>()).add(q);}for(var entry:groups.entrySet()){int k=entry.getKey();long[] mul=new long[n+k];Arrays.fill(mul,1);for(int[] q:entry.getValue()){int l=q[0],end=l+((q[1]-l)/k+1)*k,v=q[3];mul[l]=mul[l]*v%MOD;mul[end]=mul[end]*pow(v,MOD-2)%MOD;}for(int i=0;i<n;i++){if(i>=k)mul[i]=mul[i]*mul[i-k]%MOD;nums[i]=(int)(nums[i]*mul[i]%MOD);}}int ans=0;for(int x:nums)ans^=x;return ans;}
}
